import { Type } from 'class-transformer';
import { IsInt, Max, Min } from 'class-validator';
import { DEFAULT_PAGE_SIZE, MAX_PAGE_SIZE } from '../contract.constants';

export class PageQueryDto {
  @Type(() => Number)
  @IsInt()
  @Min(1)
  page = 1;

  @Type(() => Number)
  @IsInt()
  @Min(1)
  @Max(MAX_PAGE_SIZE)
  limit = DEFAULT_PAGE_SIZE;
}
libs/contract/src/lib/contract.constants.ts:4:export const DEFAULT_PAGE_SIZE = 10;
libs/contract/src/lib/contract.constants.ts:5:export const MAX_PAGE_SIZE = 100;

